package escuela.personal.controller;

import escuela.personal.dto.*;
import escuela.personal.service.*;
import escuela.admin.dto.*;
import escuela.admin.support.MensajeErrorFormulario;
import escuela.common.exception.ReglaNegocioException;
import lombok.RequiredArgsConstructor;
import jakarta.validation.Valid;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.*;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import org.springframework.http.*;
import java.io.IOException;
import java.time.LocalDate;
import java.util.*;

@Controller @RequestMapping("/admin/preparacion-nomina") @RequiredArgsConstructor
public class PreparacionNominaController {
 private final PreparacionNominaService service;
 private final ProgramacionNominaService programacion;
 private final EmpleadoService empleados;
 private final AplicacionNominaService aplicaciones;
 private void base(FiltroNomina original,Model m){var p=empleados.autorizarSalarios(false);var f=original.normalizado();m.addAttribute("filtro",f);m.addAttribute("volverUrl",f.url("/admin/preparacion-nomina"));m.addAttribute("puedeEditar",empleados.permitido("CONDICION_SALARIAL_ADMINISTRAR"));m.addAttribute("puedeAplicar",aplicaciones.puedeAplicar());var permisos=p.authorities().stream().map(x->x.getAuthority()).collect(java.util.stream.Collectors.toSet());m.addAttribute("institucionNomina",p.institucionId());m.addAttribute("puedeVerMovimiento",ModuloCatalogo.MOVIMIENTOS_FINANCIEROS.visibleCon(permisos));m.addAttribute("modulos",Arrays.stream(ModuloCatalogo.values()).filter(x->x.visibleCon(permisos)).toList());m.addAttribute("moduloActual",ModuloCatalogo.PREPARACION_NOMINA);m.addAttribute("calendarioFiltro",f.filtroCalendarioId()==null?f.filtroCalendarioTexto():programacion.calendario(f.filtroCalendarioId()).codigo()+" · "+programacion.calendario(f.filtroCalendarioId()).nombre());m.addAttribute("periodoFiltro",f.filtroPeriodoId()==null?f.filtroPeriodoTexto():programacion.periodo(f.filtroPeriodoId()).codigo()+" · "+programacion.periodo(f.filtroPeriodoId()).nombre());m.addAttribute("empleadoFiltro",f.filtroEmpleadoId()==null?f.filtroEmpleadoTexto():empleados.obtener(f.filtroEmpleadoId()).codigo()+" · "+empleados.obtener(f.filtroEmpleadoId()).nombre());}
 @GetMapping String listado(@ModelAttribute FiltroNomina filtro,Model m){base(filtro,m);try{m.addAttribute("resultado",service.listar(filtro));}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());m.addAttribute("resultado",org.springframework.data.domain.Page.empty());}return "admin/nomina-listado";}
 @GetMapping("/seleccion-manual") String nuevo(@RequestParam(required=false)Long periodoId,@RequestParam(required=false)String periodoTexto,@RequestParam(defaultValue="LISTO")String grupo,@ModelAttribute FiltroNomina filtro,@ModelAttribute FiltroCandidatosNomina candidatos,Model m){empleados.autorizarSalarios(true);var form=new BorradorNominaForm();form.setPeriodoId(periodoId);if(periodoId==null&&periodoTexto!=null&&!periodoTexto.isBlank())m.addAttribute("errorOperacion","Selecciona el periodo de la ayuda; escribir su nombre no basta.");m.addAttribute("form",form);return captura(form,grupo,filtro,candidatos,m);}
 private void candidatoBase(FiltroCandidatosNomina f,Model m){m.addAttribute("filtroCandidatos",f);m.addAttribute("consultaCandidatos",f.comoFiltro());m.addAttribute("empleadoCandidato",f.candidatoEmpleadoId()==null?f.candidatoEmpleadoTexto():empleados.obtener(f.candidatoEmpleadoId()).codigo()+" · "+empleados.obtener(f.candidatoEmpleadoId()).nombre());}
 private String captura(BorradorNominaForm form,String grupo,FiltroNomina filtro,FiltroCandidatosNomina candidatos,Model m){base(filtro,m);candidatoBase(candidatos,m);m.addAttribute("grupo",PreparacionNominaService.grupo(grupo));m.addAttribute("form",form);if(form.getPeriodoId()!=null)try{var c=service.contexto(form.getPeriodoId());m.addAttribute("contexto",c);form.setSelloPeriodo(c.sello());m.addAttribute("candidatos",service.candidatos(form.getPeriodoId(),candidatos.comoFiltro(),grupo));m.addAttribute("conteos",service.conteos(form.getPeriodoId(),candidatos.comoFiltro()));}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());}return "admin/nomina-nuevo";}
 @PostMapping("/volver") String volver(@ModelAttribute("form")BorradorNominaForm form,@RequestParam(defaultValue="LISTO")String grupo,@ModelAttribute FiltroNomina filtro,@ModelAttribute FiltroCandidatosNomina candidatos,Model m){empleados.autorizarSalarios(true);return captura(form,grupo,filtro,candidatos,m);}
 @PostMapping("/previsualizar") String previsualizar(@Valid @ModelAttribute("form")BorradorNominaForm form,BindingResult errores,@RequestParam(defaultValue="LISTO")String grupo,@ModelAttribute FiltroNomina filtro,@ModelAttribute FiltroCandidatosNomina candidatos,Model m){empleados.autorizarSalarios(true);if(!errores.hasErrors())try{var previa=service.previsualizar(form);base(filtro,m);candidatoBase(candidatos,m);m.addAttribute("grupo",grupo);m.addAttribute("previa",previa);m.addAttribute("actualizando",false);return "admin/nomina-previa";}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());}if(errores.hasErrors())m.addAttribute("errorOperacion","Completa nombre y motivo, selecciona empleados listos y revisa los campos marcados.");return captura(form,grupo,filtro,candidatos,m);}
 @PostMapping("/guardar") String guardar(@Valid @ModelAttribute("form")BorradorNominaForm form,BindingResult errores,@ModelAttribute FiltroNomina filtro,@ModelAttribute FiltroCandidatosNomina candidatos,Model m,RedirectAttributes flash){empleados.autorizarSalarios(true);if(!errores.hasErrors())try{Long id=service.guardar(form);flash.addFlashAttribute("mensaje","Borrador guardado. No es nómina autorizada ni fiscal; no se ejecutaron pagos o movimientos.");return "redirect:"+filtro.url("/admin/preparacion-nomina/"+id);}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException e){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(e));}if(errores.hasErrors())m.addAttribute("errorOperacion","Revisa nombre, motivo y selección antes de guardar.");return captura(form,"LISTO",filtro,candidatos,m);}
 @GetMapping("/{id:\\d+}") String detalle(@PathVariable Long id,@ModelAttribute FiltroNomina filtro,@RequestParam(defaultValue="0")int revisionConsulta,@RequestParam(defaultValue="0")int paginaEmpleados,@RequestParam(defaultValue="0")int paginaHistorial,@RequestParam(defaultValue="0")int paginaRevisiones,Model m){base(filtro,m);var b=service.obtener(id);int revision=revisionConsulta==0?b.revision():revisionConsulta;m.addAttribute("borrador",b);m.addAttribute("aplicacionNomina",aplicaciones.obtener(id));m.addAttribute("revisionConsulta",revision);m.addAttribute("cobertura",service.cobertura(id,revision));m.addAttribute("guardados",service.guardados(id,revision,paginaEmpleados));m.addAttribute("totales",service.totalesGuardados(id,revision));m.addAttribute("historial",service.historial(id,paginaHistorial));m.addAttribute("revisiones",service.revisiones(id,paginaRevisiones));m.addAttribute("advertencia",service.advertencia(b));return "admin/nomina-detalle";}
 @GetMapping("/{id:\\d+}/empleados/{fila:\\d+}") String empleado(@PathVariable Long id,@PathVariable Long fila,@ModelAttribute FiltroNomina filtro,Model m){base(filtro,m);m.addAttribute("borrador",service.obtener(id));m.addAttribute("empleado",service.empleadoGuardado(id,fila));m.addAttribute("lineas",service.lineas(id,fila));return "admin/nomina-empleado";}
 @GetMapping("/{id:\\d+}/actualizar") String revisarActualizacion(@PathVariable Long id,@ModelAttribute FiltroNomina filtro,Model m){empleados.autorizarSalarios(true);try{var b=service.obtener(id);var previa=service.actualizacion(id);var f=new BorradorNominaForm();f.setPeriodoId(b.periodoId());f.setSelloPeriodo(previa.contexto().sello());f.setNombre(b.nombre());f.setSeleccion(previa.candidatos().stream().filter(e->e.grupo().equals("LISTO")).map(PreparacionNominaService.Candidato::token).toList());base(filtro,m);m.addAttribute("form",f);m.addAttribute("borrador",b);m.addAttribute("previa",previa);m.addAttribute("totalesAnteriores",service.totalesGuardados(id,b.revision()));m.addAttribute("actualizando",true);return "admin/nomina-previa";}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());return detalle(id,filtro,0,0,0,0,m);}}
 @PostMapping("/{id:\\d+}/actualizar") String actualizar(@PathVariable Long id,@RequestParam Long version,@Valid @ModelAttribute("form")BorradorNominaForm form,BindingResult errores,@ModelAttribute FiltroNomina filtro,Model m){empleados.autorizarSalarios(true);if(!errores.hasErrors())try{service.actualizar(id,version,form);m.addAttribute("mensaje","Nueva revisión guardada. Las revisiones anteriores se conservan; no se movió dinero.");}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException e){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(e));}if(errores.hasErrors())m.addAttribute("errorOperacion","Completa el motivo de actualización y revisa la selección; vuelve a Revisar actualización para comprobar sus diferencias.");m.addAttribute("motivoCapturado",form.getMotivo());m.addAttribute("tabInicial","gestion");return detalle(id,filtro,0,0,0,0,m);}
 @PostMapping("/{id:\\d+}/cancelar") String cancelar(@PathVariable Long id,@RequestParam Long version,@RequestParam String motivo,@ModelAttribute FiltroNomina filtro,Model m){empleados.autorizarSalarios(true);try{service.cancelar(id,version,motivo);m.addAttribute("mensaje","Borrador cancelado con historial. No se cancelaron pagos ni se alteraron cuentas o configuraciones originales.");}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException e){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(e));m.addAttribute("motivoCapturado",motivo);}m.addAttribute("tabInicial","gestion");return detalle(id,filtro,0,0,0,0,m);}
 @GetMapping("/periodos/buscar") @ResponseBody ResponseEntity<ResultadoAutocompletado> periodos(@RequestParam(defaultValue="")String q){var filas=service.periodos(q);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new ResultadoAutocompletado(filas.stream().limit(10).toList(),filas.size()>10));}
 @GetMapping("/excel") void excel(@ModelAttribute FiltroNomina filtro,HttpServletResponse response)throws IOException{service.listar(filtro.pagina(0,100));try(var book=libro(response,"preparacion-nomina")){try{var hoja=book.createSheet("Borradores");cabecera(hoja,"Folio","Nombre","Estado","Revisión","Calendario histórico","Periodo","Inicio","Fin","Pago previsto","Empleados","Propuesto sin impuestos","Moneda");int fila=1,pagina=0;boolean mas;do{var page=service.listar(filtro.pagina(pagina++,100));mas=page.hasNext();for(var b:page)escribir(hoja.createRow(fila++),b.folio(),b.nombre(),b.estado(),b.revision(),b.calendario(),b.periodoCodigo()+" · "+b.periodoNombre(),fecha(b.inicio()),fecha(b.fin()),fecha(b.pago()),b.cantidad(),b.propuesto(),b.moneda());}while(mas);book.write(response.getOutputStream());}finally{book.dispose();}}}
 @GetMapping("/candidatos/excel") void candidatosExcel(@RequestParam Long periodoId,@RequestParam(defaultValue="LISTO")String grupo,@ModelAttribute FiltroCandidatosNomina consulta,HttpServletResponse response)throws IOException{var filtro=consulta.comoFiltro();service.candidatos(periodoId,filtro,grupo);try(var book=libro(response,"candidatos-nomina")){try{var hoja=book.createSheet("Candidatos");cabecera(hoja,"Código","Empleado","Clasificación","Motivo","Sueldo","Percepciones","Deducciones","Aportaciones escuela","Propuesto sin impuestos","Moneda");int fila=1,pagina=0;boolean mas;do{var page=service.candidatos(periodoId,filtro.pagina(pagina++,100),grupo);mas=page.hasNext();for(var e:page)escribir(hoja.createRow(fila++),e.codigo(),e.nombre(),e.grupo(),e.motivo(),e.sueldo(),e.percepciones(),e.deducciones(),e.aportaciones(),e.propuesto(),e.moneda());}while(mas);book.write(response.getOutputStream());}finally{book.dispose();}}}
 @GetMapping("/{id:\\d+}/excel") void detalleExcel(@PathVariable Long id,@RequestParam(defaultValue="0")int revisionConsulta,HttpServletResponse response)throws IOException{var b=service.obtener(id);int rev=revisionConsulta==0?b.revision():revisionConsulta;service.guardados(id,rev,0);try(var book=libro(response,b.folio()+"-revision-"+rev)){try{var hoja=book.createSheet("Empleados");cabecera(hoja,"Folio","Revisión","Código","Empleado","Sueldo","Percepciones","Deducciones","Aportaciones escuela","Propuesto sin impuestos","Moneda");var detalle=book.createSheet("Desglose");cabecera(detalle,"Código empleado","Empleado","Código concepto","Concepto histórico","Tipo","Importe","Inicio vigencia","Fin vigencia");int fila=1,linea=1,pagina=0;boolean mas;do{var page=service.guardados(id,rev,pagina++);mas=page.hasNext();for(var e:page){escribir(hoja.createRow(fila++),b.folio(),rev,e.codigo(),e.nombre(),e.sueldo(),e.percepciones(),e.deducciones(),e.aportaciones(),e.propuesto(),e.moneda());for(var l:service.lineas(id,e.id()))escribir(detalle.createRow(linea++),e.codigo(),e.nombre(),l.codigo(),l.nombre(),l.naturaleza(),l.importe(),fechaTexto(l.inicio()),fechaTexto(l.fin()));}}while(mas);book.write(response.getOutputStream());}finally{book.dispose();}}}
 private static org.apache.poi.xssf.streaming.SXSSFWorkbook libro(HttpServletResponse r,String nombre){r.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");r.setHeader("Content-Disposition","attachment; filename="+nombre+".xlsx");r.setHeader("Cache-Control","no-store");return new org.apache.poi.xssf.streaming.SXSSFWorkbook(100);}
 private static void cabecera(org.apache.poi.ss.usermodel.Sheet hoja,String... nombres){escribir(hoja.createRow(0),(Object[])nombres);for(int n=0;n<nombres.length;n++)hoja.setColumnWidth(n,30*256);hoja.createFreezePane(0,1);}
 private static void escribir(org.apache.poi.ss.usermodel.Row fila,Object... valores){for(int n=0;n<valores.length;n++){var cell=fila.createCell(n);if(valores[n] instanceof Number valor)cell.setCellValue(valor.doubleValue());else cell.setCellValue(Objects.toString(valores[n],""));}}
 private static String fecha(LocalDate fecha){return fecha.format(java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy"));}
 private static String fechaTexto(String texto){return texto==null?"Sin fin":fecha(LocalDate.parse(texto));}

 @GetMapping("/{id:\\d+}/aplicacion") String aplicacion(@PathVariable Long id,@ModelAttribute FiltroNomina filtro,Model m){aplicaciones.validarBorrador(id);var f=new AplicarNominaForm();f.setVersion(service.obtener(id).version());f.setMotivo("Aplicación de nómina revisada del periodo "+service.obtener(id).periodoCodigo()+".");m.addAttribute("formAplicacion",f);return formularioAplicacion(id,filtro,m);}
 private String formularioAplicacion(Long id,FiltroNomina filtro,Model m){base(filtro,m);aplicaciones.validarBorrador(id);var b=service.obtener(id);m.addAttribute("borrador",b);m.addAttribute("totales",service.totalesGuardados(id,b.revision()));return "admin/nomina-aplicacion";}
 @PostMapping("/{id:\\d+}/revisar-aplicacion") String revisarAplicacion(@PathVariable Long id,@Valid @ModelAttribute("formAplicacion")AplicarNominaForm form,BindingResult errores,@ModelAttribute FiltroNomina filtro,Model m){if(!errores.hasErrors())try{var v=aplicaciones.revisar(id,form);base(filtro,m);m.addAttribute("vistaAplicacion",v);return "admin/nomina-aplicacion-previa";}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());}return formularioAplicacion(id,filtro,m);}
 @PostMapping("/{id:\\d+}/aplicar") String aplicar(@PathVariable Long id,@Valid @ModelAttribute("formAplicacion")AplicarNominaForm form,BindingResult errores,@RequestParam(defaultValue="")String sello,@RequestParam(defaultValue="false")boolean salidaConfirmada,@ModelAttribute FiltroNomina filtro,Model m,RedirectAttributes flash){if(!errores.hasErrors())try{aplicaciones.aplicar(id,form,sello,salidaConfirmada);flash.addFlashAttribute("mensaje","Nómina aplicada. Se registró un único egreso en la cuenta elegida y la revisión quedó bloqueada. No se envió ninguna transferencia bancaria.");return "redirect:"+filtro.url("/admin/preparacion-nomina/"+id);}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException e){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(e));}if(!service.obtener(id).estado().equals("BORRADOR")){m.addAttribute("errorOperacion","La nómina ya fue aplicada o cancelada; no se registró otro egreso.");return detalle(id,filtro,0,0,0,0,m);}return formularioAplicacion(id,filtro,m);}
 @GetMapping("/{id:\\d+}/cuentas-aplicacion") @ResponseBody ResponseEntity<ResultadoAutocompletado> cuentasAplicacion(@PathVariable Long id,@RequestParam(defaultValue="")String q){var r=aplicaciones.cuentas(id,q);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new ResultadoAutocompletado(r.stream().limit(10).toList(),r.size()>10));}
 @GetMapping("/{id:\\d+}/motivos-aplicacion") @ResponseBody ResponseEntity<ResultadoAutocompletado> motivosAplicacion(@PathVariable Long id,@RequestParam(defaultValue="")String q){var r=aplicaciones.motivos(id,q);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new ResultadoAutocompletado(r.stream().limit(10).toList(),r.size()>10));}

 @GetMapping("/nuevo") String inicio(@RequestParam(required=false)Long periodoId,@ModelAttribute FiltroNomina filtro,Model m){empleados.autorizarSalarios(true);base(filtro,m);m.addAttribute("periodoId",periodoId);m.addAttribute("periodoTexto",periodoId==null?"":service.contexto(periodoId).periodo().codigo()+" · "+service.contexto(periodoId).periodo().nombre());return "admin/nomina-inicio";}
 @PostMapping("/preparar-periodo") String preparar(@RequestParam(required=false) Long periodoId,@RequestParam(defaultValue="TODOS")String modo,@ModelAttribute FiltroNomina filtro,Model m,RedirectAttributes flash){empleados.autorizarSalarios(true);try{if(periodoId==null)throw new ReglaNegocioException("Selecciona un periodo programado desde la ayuda de búsqueda.");var id=service.prepararPeriodo(periodoId,modo);return "redirect:"+filtro.url("/admin/preparacion-nomina/vista/"+id);}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());return inicio(null,filtro,m);}}
 @PostMapping("/{id:\\d+}/preparar-actualizacion") String prepararActualizacion(@PathVariable Long id,@ModelAttribute FiltroNomina filtro,Model m){empleados.autorizarSalarios(true);try{return "redirect:"+filtro.url("/admin/preparacion-nomina/vista/"+service.prepararActualizacion(id));}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());m.addAttribute("tabInicial","gestion");return detalle(id,filtro,0,0,0,0,m);}}
 @GetMapping("/vista/{id}") String vistaPeriodo(@PathVariable UUID id,@ModelAttribute FiltroNomina filtro,@ModelAttribute FiltroPreparacionNomina consulta,Model m){base(filtro,m);try{var l=service.preparacion(id);var f=consulta.normalizado();m.addAttribute("lote",l);m.addAttribute("consulta",f);m.addAttribute("consultaEmpleadoTexto",f.consultaEmpleadoId()==null?f.consultaEmpleadoTexto():empleados.obtener(f.consultaEmpleadoId()).codigo()+" · "+empleados.obtener(f.consultaEmpleadoId()).nombre());m.addAttribute("totales",service.totalesPreparacion(id));m.addAttribute("conteos",service.conteosPreparacion(id));m.addAttribute("resultado",service.filasPreparacion(id,f));m.addAttribute("rutaLote","/admin/preparacion-nomina/vista/"+id);if(l.borradorId()!=null)m.addAttribute("totalesAnteriores",service.totalesGuardados(l.borradorId(),service.obtener(l.borradorId()).revision()));return "admin/nomina-periodo-previa";}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());return inicio(null,filtro,m);}}
 @PostMapping("/vista/{id}/seleccionar") String seleccionarPeriodo(@PathVariable UUID id,@RequestParam Long version,@RequestParam Long empleadoId,@RequestParam boolean incluir,@ModelAttribute FiltroNomina filtro,@ModelAttribute FiltroPreparacionNomina consulta,RedirectAttributes flash){empleados.autorizarSalarios(true);String destino=consulta.url(filtro,"/admin/preparacion-nomina/vista/"+id,consulta.normalizado().paginaConsulta());try{service.seleccionarPreparacion(id,version,empleadoId,incluir);return "redirect:"+destino+"#nomina-empleado-"+empleadoId;}catch(ReglaNegocioException e){flash.addFlashAttribute("errorOperacion",e.getMessage());}return "redirect:"+destino;}
 @PostMapping("/vista/{id}/guardar") String guardarPeriodo(@PathVariable UUID id,@RequestParam Long version,@RequestParam(required=false)String nombre,@RequestParam(required=false)String motivo,@ModelAttribute FiltroNomina filtro,@ModelAttribute FiltroPreparacionNomina consulta,Model m,RedirectAttributes flash){empleados.autorizarSalarios(true);try{Long b=service.guardarPreparacion(id,version,nombre,motivo);flash.addFlashAttribute("mensaje","Borrador revisado guardado con el total general y detalle por empleado. No se autorizó ni pagó nómina y no se movió dinero.");return "redirect:"+filtro.url("/admin/preparacion-nomina/"+b);}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException e){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(e));m.addAttribute("nombreCapturado",nombre);m.addAttribute("motivoCapturado",motivo);return vistaPeriodo(id,filtro,consulta,m);}}
 @PostMapping("/vista/{id}/descartar") String descartarPeriodo(@PathVariable UUID id,@RequestParam Long version,@ModelAttribute FiltroNomina filtro,RedirectAttributes flash){empleados.autorizarSalarios(true);try{service.descartarPreparacion(id,version);flash.addFlashAttribute("mensaje","Vista previa descartada. Los borradores existentes y las configuraciones no cambiaron.");}catch(ReglaNegocioException e){flash.addFlashAttribute("errorOperacion",e.getMessage());}return "redirect:"+filtro.url("/admin/preparacion-nomina");}
 @GetMapping("/vista/{id}/empleados/{empleadoId}") String desglosePeriodo(@PathVariable UUID id,@PathVariable Long empleadoId,@ModelAttribute FiltroNomina filtro,@ModelAttribute FiltroPreparacionNomina consulta,Model m){base(filtro,m);m.addAttribute("lote",service.preparacion(id));m.addAttribute("empleado",service.filaPreparacion(id,empleadoId));m.addAttribute("lineas",service.lineasPreparacion(id,empleadoId));m.addAttribute("volverLote",consulta.url(filtro,"/admin/preparacion-nomina/vista/"+id,consulta.normalizado().paginaConsulta()));return "admin/nomina-periodo-empleado";}
 @GetMapping("/vista/{id}/excel") void excelPeriodo(@PathVariable UUID id,@ModelAttribute FiltroPreparacionNomina consulta,HttpServletResponse response)throws IOException{var l=service.preparacion(id);var t=service.totalesPreparacion(id);service.filasPreparacion(id,consulta);try(var book=libro(response,"vista-previa-"+l.codigo())){try{var resumen=book.createSheet("Resumen global");cabecera(resumen,"Periodo","Inicio","Fin","Empleados seleccionados","Sueldos","Percepciones","Deducciones","Aportaciones escuela","Propuesto sin impuestos","Moneda");escribir(resumen.createRow(1),l.codigo(),fecha(l.inicio()),fecha(l.fin()),t.empleados(),t.sueldo(),t.percepciones(),t.deducciones(),t.aportaciones(),t.propuesto(),l.moneda());escribir(resumen.createRow(3),"Resumen de toda la selección; la hoja Consulta respeta los filtros de tabla.");var hoja=book.createSheet("Consulta");cabecera(hoja,"Código","Empleado","Clasificación","Incluido","Motivo","Sueldo","Percepciones","Deducciones","Aportaciones escuela","Propuesto sin impuestos","Moneda");int pagina=0,fila=1;boolean mas;do{var f=consulta.normalizado();var page=service.filasPreparacion(id,new FiltroPreparacionNomina(f.buscar(),f.grupoConsulta(),pagina++,f.consultaEmpleadoId(),null));mas=page.hasNext();for(var e:page)escribir(hoja.createRow(fila++),e.codigo(),e.nombre(),e.grupo(),e.seleccionado()?"Sí":"No",e.motivo(),e.sueldo(),e.percepciones(),e.deducciones(),e.aportaciones(),e.propuesto(),l.moneda());}while(mas);book.write(response.getOutputStream());}finally{book.dispose();}}}
}
